  'agents.ctx.compact_tip':            'Most azonnal összefoglalja a beszélgetést, hogy kevesebb helyet foglaljon. A lényeg megmarad, a részletek egy része összevonódik. Az itt beírt ezer-token szám NEM ehhez a gombhoz tartozik: az az automatikus tömörítés határa.',
  'agents.ctx.clear':                  'Törlés',
  'agents.ctx.clear_tip':              'Teljesen kiüríti a beszélgetést, az ágens friss lappal indul. Visszavonhatatlan.',
  'agents.ctx.auto':                   'Automatikus tömörítés',
  'agents.ctx.auto_tip':               'Ha bekapcsolod, a rendszer magától tömöríti a beszélgetést, ha az túl nagyra nő (a lenti ezer-token határ fölött). Összefoglalót készít, nem dob el mindent -- teljes törlés SOHA nem történik magától, csak ha te nyomod meg a Törlés gombot. Fontos: csak akkor tud lefutni, amikor az ágens épp NEM dolgozik, tehát egy folyamatosan dolgozó ágensnél a szám a határ fölé mehet, amíg le nem áll.',
  'agents.ctx.unit':                   'ezer token fölött',
  'agents.ctx.current':                'Jelenleg:',
  'agents.ctx.current_empty':          'Jelenleg: még nem dolgozott (elindult, de egy fordulót sem futtatott)',
